const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.client = new AWS.SecretsManager({ region: process.env.AWS_REGION });
  }

  async loadSecrets(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      this.secrets = JSON.parse(data.SecretString || data.SecretBinary);

      // Validate required secrets
      const required = ['DATABASE_URL', 'JWT_SECRET', 'STRIPE_SECRET_KEY'];
      const missing = required.filter(key => !this.secrets[key]);

