### Example: Secure Secret Loading Pattern

```javascript
// secrets.js
class SecureConfig {
  constructor() {
    this.secrets = new Map();
    this.loadSecrets();
  }

  loadSecrets() {
    // Only allow environment variables in production
    if (process.env.NODE_ENV === 'production') {
      this.validateNoEnvFiles();
    }

    // Load and validate each secret
    this.setSecret('DATABASE_URL', process.env.DATABASE_URL, { 
      required: true,
      pattern: /^postgres:\/\//
    });

    this.setSecret('JWT_SECRET', process.env.JWT_SECRET, {
      required: true,
      minLength: 32
    });

    // Mask secrets in memory
    this._maskSecrets();
  }

  setSecret(name, value, options = {}) {
    if (options.required && !value) {
      throw new Error(`Required secret ${name} is missing`);
    }

    if (value && options.minLength && value.length < options.minLength) {
      throw new Error(`Secret ${name} does not meet minimum length requirement`);
    }

    if (value && options.pattern && !options.pattern.test(value)) {
      throw new Error(`Secret ${name} does not match required pattern`);
    }

    // Store with access logging
    Object.defineProperty(this, name, {
      get: () => {
        console.log(`[AUDIT] Secret ${name} accessed at ${new Date().toISOString()}`);
        return this.secrets.get(name);
      },
      enumerable: false
    });

    this.secrets.set(name, value);
  }

  _maskSecrets() {
    // Prevent accidental serialization of secrets
    this.toJSON = () => ({
      secrets: '[REDACTED]',
      loadedAt: new Date().toISOString()
    });
  }
}

module.exports = new SecureConfig();
```

