/**
 * Secrets Manager Integration Module
 * Supports AWS Secrets Manager, Azure Key Vault, or HashiCorp Vault
 * 
 * Usage:
 *   const secrets = await loadSecrets();
 *   const dbPassword = secrets.database.password;
 */

const config = require('./config');

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.ttl = 5 * 60 * 1000; // 5 minutes cache
  }

  /**
   * AWS Secrets Manager Implementation
   */
  async loadFromAWSSecretsManager(secretName) {
    // Requires: npm install @aws-sdk/client-secrets-manager
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({
      region: config.aws.region,
      credentials: {
        accessKeyId: config.aws.accessKeyId,
        secretAccessKey: config.aws.secretAccessKey
      }
    });

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      if (response.SecretString) {
        return JSON.parse(response.SecretString);
      }
      return null;
    } catch (error) {
      console.error('Failed to load secret from AWS:', error.message);
      throw error;
    }
  }

  /**
   * HashiCorp Vault Implementation
   */
  async loadFromVault(path) {
    // Requires: npm install node-vault
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });

    try {
      const result = await vault.read(path);
      return result.data;
    } catch (error) {
      console.error('Failed to load secret from Vault:', error.message);
      throw error;
    }
  }

  /**
   * Kubernetes Secrets (Container-native)
   */
  loadFromKubernetes(secretName) {
    const fs = require('fs');
    const path = `/var/run/secrets/kubernetes.io/serviceaccount/${secretName}`;

    try {
      if (fs.existsSync(path)) {
        return fs.readFileSync(path, 'utf8').trim();
      }
      throw new Error(`Secret not found at ${path}`);
    } catch (error) {
      console.error('Failed to load secret from Kubernetes:', error.message);
      throw error;
    }
  }

  /**
   * Get secret with caching
   */
  async get(key) {
    const cached = this.cache.get(key);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    // Load from configured source based on environment
    let secret;
    if (process.env.SECRETS_PROVIDER === 'aws') {
      secret = await this.loadFromAWSSecretsManager(key);
    } else if (process.env.SECRETS_PROVIDER === 'vault') {
      secret = await this.loadFromVault(key);
    } else {
      // Fallback to environment variables (development only)
      secret = process.env[key];
    }

    // Cache the value
    this.cache.set(key, {
      value: secret,
      timestamp: Date.now()
    });

    return secret;
  }

  /**
   * Clear cache (useful for rotation)
   */
  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();

