      .trim()
      .isLength({ min: 1, max: 100 })
      .escape()  // Sanitizes HTML
      .withMessage('Name is required and must be under 100 characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
  ]),
