// config/secrets.js
const fs = require('fs');
const path = require('path');

const REQUIRED_SECRETS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'STRIPE_SECRET_KEY'
];

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.isLoaded = false;
  }

  async load() {
    if (this.isLoaded) return this.secrets;

    const env = process.env.NODE_ENV || 'development';

    switch(env) {
      case 'production':
        await this.loadFromCloud();
        break;
      case 'staging':
        await this.loadFromCloud();
        break;
      default:
        this.loadFromEnv();
    }

    this.validate();
    this.isLoaded = true;
    return this.secrets;
  }

  loadFromEnv() {
    // Only for local development
    require('dotenv').config({ path: '.env.local' });
    REQUIRED_SECRETS.forEach(secret => {
      this.secrets[secret] = process.env[secret];
    });
  }

  async loadFromCloud() {
    // Load from AWS/GCP/Azure secrets manager
    const { getSecrets } = require('./cloud-secrets');
    this.secrets = await getSecrets();
  }

  validate() {
    const missing = REQUIRED_SECRETS.filter(s => !this.secrets[s]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  // Prevent accidental logging
  toJSON() {
    return { loaded: this.isLoaded, secrets: '[REDACTED]' };
  }
}

module.exports = new SecretsManager();
