#### Option A: AWS Secrets Manager (Recommended for AWS environments)

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

let cachedSecrets = null;
let cacheExpiry = null;

async function getSecrets() {
  // Cache secrets for 5 minutes to reduce API calls
  if (cachedSecrets && cacheExpiry > Date.now()) {
    return cachedSecrets;
  }

  const command = new GetSecretValueCommand({
    SecretId: process.env.SECRETS_MANAGER_ARN
  });

  try {
    const response = await client.send(command);
    cachedSecrets = JSON.parse(response.SecretString);
    cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 min cache
    return cachedSecrets;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw error;
  }
}

// Usage in app.js
async function initializeApp() {
  const secrets = await getSecrets();

  const db = createDatabaseConnection(secrets.databaseUrl);
  const stripe = new Stripe(secrets.stripeSecretKey);

  // ... rest of app initialization
}

module.exports = { getSecrets };
```

