      AWS_REGION: process.env.AWS_REGION || 'us-east-1',
      ...secrets // Secrets override defaults
    };

    await validateEnv(combinedEnv);

  } catch (err) {
    console.error('Failed to load secrets from AWS Secrets Manager:', err.message);
    process.exit(1);
  }
};

const validateEnv = async (envVars) => {
  const schema = Joi.object({
    NODE_ENV: Joi.string().valid('development', 'test', 'production').required(),
    PORT: Joi.number().default(3000),
    DATABASE_URL: Joi.string().uri().required(),
    JWT_SECRET: Joi.string().min(32).required(),
    ANTHROPIC_API_KEY: Joi.string().required(),
    STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(live|test)_/).required(),
    AWS_REGION: Joi.string().required(),
  }).unknown(false);

  const { error, value } = schema.validate(envVars);
  if (error) {
    throw new Error(`Environment validation failed: ${error.message}`);
  }

  env = value;
};

// ============================================
// SAFETY CHECKS
// ============================================

const securityChecks = () => {
  // Ensure JWT_SECRET is not a default/weak value
  const weakSecrets = ['changeme', 'secret', 'password', 'admin', '123456'];
  if (weakSecrets.includes(env.JWT_SECRET.toLowerCase())) {
    throw new Error('JWT_SECRET is using a weak/default value');
  }

  // Warn about test keys in production
  if (env.NODE_ENV === 'production') {
    if (env.STRIPE_SECRET_KEY.startsWith('sk-test-')) {
      console.warn('WARNING: Using Stripe test key in production!');
    }
    if (env.ANTHROPIC_API_KEY.includes('test')) {
      console.warn('WARNING: Anthropic key appears to be a test key!');
    }
  }
};

// ============================================
// APP INITIALIZATION
// ============================================

const initApp = async () => {
  await loadSecrets();
  securityChecks();

  const app = express();

  // Security middleware
  app.use(helmet());
  app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

  // Health check (no secrets exposed)
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok',
      // Deliberately minimal info
      timestamp: Math.floor(Date.now() / 1000) // Unix timestamp, less precise
    });
  });

  // Sample protected route
  app.get('/api/config', (req, res) => {
    // NEVER return actual secrets
    res.json({
      environment: env.NODE_ENV,
      features: {
        payments: env.STRIPE_SECRET_KEY ? true : false,
        ai: env.ANTHROPIC_API_KEY ? true : false
      }
    });
  });

  // Global error handler
  app.use((err, req, res, next) => {
    // Log error (with sanitized details)
    console.error('Error:', {
      message: err.message,
      stack: env.NODE_ENV === 'development' ? err.stack : undefined,
      path: req.path,
      method: req.method
    });

    // Never expose stack traces or env vars in production
    res.status(err.status || 500).json({
      error: env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : err.message
    });
  });

  app.listen(env.PORT, () => {
    console.log(`Server running on port ${env.PORT} in ${env.NODE_ENV} mode`);
  });
};

initApp().catch(console.error);

module.exports = { app, env };
```

